// ─── Chat Preview — Responsive ───────────────────────────────────────────────────
function ChatPreview({ agent }: { agent: Agent }) {
  const [messages, setMessages] = useState<{ role: "user" | "bot"; text: string }[]>([]);
  const [input, setInput] = useState("");
  const [sending, setSending] = useState(false);

  async function send() {
    if (!input.trim() || sending) return;
    const txt = input;
    setInput("");
    setMessages(m => [...m, { role: "user", text: txt }]);
    setSending(true);
    try {
      const history = messages.map(m => ({ role: (m.role === "user" ? "user" : "assistant") as "user" | "assistant", content: m.text }));
      const reply = await agentsApi.chatWithAgent(agent, history, txt);
      setMessages(m => [...m, { role: "bot", text: reply || "(sem resposta)" }]);
    } catch (err: any) {
      setMessages(m => [...m, { role: "bot", text: `Erro: ${err?.message || "falha ao falar com a IA."}` }]);
    } finally {
      setSending(false);
    }
  }

  return (
    <div className="editor-chat-panel">
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "10px 12px 8px", flexShrink: 0 }}>
        <span style={{ fontFamily: "Montserrat, sans-serif", fontWeight: 600, fontSize: 11, color: "#222" }}>{agent.nome || "Preview"}</span>
        <button
          onClick={() => setMessages([])}
          style={{
            display: "flex",
            alignItems: "center",
            gap: 6,
            border: "1px solid #d8d8d8",
            borderRadius: 8,
            padding: "0 12px",
            height: 30,
            background: "white",
            cursor: "pointer",
            fontFamily: "Montserrat, sans-serif",
            fontSize: 10,
            color: "rgba(0,0,0,0.68)"
          }}
        >
          <RotateCcw size={11} />
          RESETAR CHAT
        </button>
      </div>

      <div style={{ flex: 1, padding: "10px 14px 0", display: "flex", flexDirection: "column", gap: 12, minHeight: 0 }}>
        {messages.length === 0 && (
          <div style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 14 }}>
            <div style={{ width: 78, height: 78, borderRadius: 28, background: "#f7f7f7", display: "flex", alignItems: "center", justifyContent: "center" }}>
              <MessageSquare size={32} color="rgba(0,0,0,0.55)" strokeWidth={1.7} />
            </div>
            <span style={{ fontFamily: "Montserrat, sans-serif", fontSize: 11, color: "rgba(0,0,0,0.68)", letterSpacing: 0.2 }}>INICIE UMA CONVERSA</span>
          </div>
        )}
        {messages.map((m, i) => (
          <div key={i} style={{ display: "flex", justifyContent: m.role === "user" ? "flex-end" : "flex-start" }}>
            <div style={{ maxWidth: "75%", padding: "8px 14px", borderRadius: 12, background: m.role === "user" ? "black" : "#f5f5f5", color: m.role === "user" ? "white" : "black", fontFamily: "Montserrat, sans-serif", fontSize: 13 }}>
              {m.text}
            </div>
          </div>
        ))}
      </div>

      <div style={{ padding: "12px 12px 14px", flexShrink: 0 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, border: "1px solid #d8d8d8", borderRadius: 6, height: 32, paddingLeft: 12, paddingRight: 8, background: "white" }}>
          <input
            value={input}
            onChange={e => setInput(e.target.value)}
            onKeyDown={e => e.key === "Enter" && send()}
            placeholder={sending ? "Aguardando resposta..." : "Digite uma mensagem..."}
            disabled={sending}
            style={{ flex: 1, background: "transparent", border: "none", outline: "none", fontFamily: "Montserrat, sans-serif", fontSize: 10, color: "#222" }}
          />
          <button onClick={send} disabled={sending} style={{ background: "none", border: "none", cursor: sending ? "default" : "pointer", padding: 0, lineHeight: 0, opacity: sending ? 0.5 : 1 }}>
            <Send size={14} color="rgba(0,0,0,0.65)" />
          </button>
        </div>
      </div>
    </div>
  );
}

// ─── Tab: Geral ───────────────────────────────────────────────────────────────
const EMOJI_OPTIONS = ["📧", "💬", "🚀", "⚙️", "🔔", "🤖", "🎯", "💡", "📊", "🔍", "📝", "✅", "❌", "⚠️", "ℹ️"];

function TabGeral({ agent, onChange }: { agent: Agent; onChange: (a: Agent) => void }) {
  const fileRef = useRef<HTMLInputElement>(null);
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);
  const [globalConfirmOpen, setGlobalConfirmOpen] = useState(false);
  const handleAvatar = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]; if (!file) return;
    const r = new FileReader(); r.onload = ev => onChange({ ...agent, avatar: ev.target?.result as string }); r.readAsDataURL(file);
  };
  function handleCopy(value: string, feedback: string) {
    navigator.clipboard.writeText(value);
    toast.success(feedback);
  }

  function handleDescricaoChange(value: string) {
    const sanitized = value.replace(/[^a-zA-Z0-9\s.,!?;:'"()-]/g, '');
    if (sanitized.length <= 500) {
      onChange({ ...agent, descricao: sanitized });
    }
  }

  function handleMakeGlobal() {
    onChange({ ...agent, isGlobal: true });
    setGlobalConfirmOpen(false);
    toast.success("Agora esse agente está disponível para todos!");
  }

  return (
    <div className="editor-panel-content" style={{ flex: 1, overflowY: "auto", padding: "12px 0 0", display: "flex", flexDirection: "column", gap: 14 }}>
      <div style={{ display: "flex", gap: 10, alignItems: "flex-start" }}>
        <div style={{ width: 40, flexShrink: 0 }}>
          <LabelWithInfo label="EMOJI" />
          <div style={{ position: "relative" }}>
            <button
              onClick={() => setShowEmojiPicker(!showEmojiPicker)}
              style={{ width: 36, height: 32, borderRadius: 6, border: "1px solid #d7d7d7", background: "white", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 20 }}
            >
              {agent.emoji || "🤖"}
            </button>
            {showEmojiPicker && (
              <div style={{
                position: "absolute",
                top: "calc(100% + 8px)",
                left: 0,
                zIndex: 100,
                background: "white",
                border: "1px solid #d7d7d7",
                borderRadius: 8,
                padding: 8,
                boxShadow: "0 4px 12px rgba(0,0,0,0.15)",
                display: "grid",
                gridTemplateColumns: "repeat(5, 1fr)",
                gap: 4
              }}>
                {EMOJI_OPTIONS.map(emoji => (
                  <button
                    key={emoji}
                    onClick={() => { onChange({ ...agent, emoji }); setShowEmojiPicker(false); }}
                    style={{
                      width: 32,
                      height: 32,
                      borderRadius: 4,
                      border: agent.emoji === emoji ? "2px solid black" : "1px solid #e0e0e0",
                      background: "white",
                      cursor: "pointer",
                      fontSize: 18,
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center"
                    }}
                  >
                    {emoji}
                  </button>
                ))}
              </div>
            )}
          </div>
        </div>
        <div style={{ flex: 1, minWidth: 0 }}>
          <LabelWithInfo label="NOME DO AGENTE" />
          <input
            value={agent.nome}
            onChange={e => onChange({ ...agent, nome: e.target.value })}
            placeholder=""
            style={{ width: "100%", height: 32, borderRadius: 6, border: "1px solid #d7d7d7", padding: "0 12px", fontFamily: "Montserrat, sans-serif", fontSize: 11, outline: "none", background: "white", boxSizing: "border-box" }}
          />
        </div>
      </div>

      <div>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 6 }}>
          <LabelWithInfo label="DESCRIÇÃO (PARA A IA ENTENDER QUANDO USAR)" />
          <span style={{ fontFamily: "Montserrat, sans-serif", fontSize: 9, color: agent.descricao.length >= 500 ? "#ef4444" : "rgba(0,0,0,0.5)" }}>
            {agent.descricao.length} / 500 caracteres
          </span>
        </div>
        <textarea
          value={agent.descricao}
          onChange={e => handleDescricaoChange(e.target.value)}
          placeholder=""
          maxLength={500}
          style={{ width: "100%", height: 78, borderRadius: 6, border: agent.descricao.length >= 500 ? "1px solid #ef4444" : "1px solid #d7d7d7", padding: 12, fontFamily: "Montserrat, sans-serif", fontSize: 11, outline: "none", resize: "none", background: "white", boxSizing: "border-box" }}
        />
      </div>

      <div>
        <div style={{ fontFamily: "Montserrat, sans-serif", fontSize: 10, color: "rgba(0,0,0,0.68)", marginBottom: 8 }}>EMBED DO AGENTE</div>
        <div style={{ background: "white", border: "1px solid #d7d7d7", borderRadius: 6, padding: 12, display: "flex", flexDirection: "column", gap: 10 }}>
          {[
            {
              label: "LINK DE COMPARTILHAMENTO",
              value: agent.embed.linkCompartilhamento,
              feedback: "Link de compartilhamento copiado!",
              tooltip: "Link direto para abrir o chat do agente em uma nova aba ou compartilhar com outras pessoas.",
            },
            {
              label: "IFRAME",
              value: agent.embed.iframe,
              feedback: "Iframe copiado!",
              tooltip: "Codigo para embutir o chat do agente dentro de um site ou pagina externa.",
            },
            {
              label: "CHAT WIDGET",
              value: agent.embed.chatWidget,
              feedback: "Chat widget copiado!",
              tooltip: "Script para adicionar um botao ou janela flutuante do agente no seu site.",
            },
          ].map(item => (
            <div key={item.label}>
              <LabelWithInfo label={item.label} info tooltipText={item.tooltip} />
              <div
                onClick={() => handleCopy(item.value, item.feedback)}
                style={{ display: "flex", alignItems: "center", background: "white", border: "1px solid #d7d7d7", borderRadius: 4, height: 28, paddingLeft: 10, paddingRight: 8, gap: 8, cursor: "pointer" }}
              >
                <span style={{ flex: 1, fontFamily: "Montserrat, sans-serif", fontSize: 10, color: "rgba(0,0,0,0.58)", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                  {item.value}
                </span>
                <button
                  onClick={e => { e.stopPropagation(); handleCopy(item.value, item.feedback); }}
                  style={{ background: "none", border: "none", cursor: "pointer", padding: 0, lineHeight: 0 }}
                >
                  <Copy size={10} color="#7a7a7a" />
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>

      <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
        <div style={{ background: "white", border: "1px solid #d7d7d7", borderRadius: 6, padding: "10px 12px", minHeight: 42, display: "flex", alignItems: "center", gap: 10 }}>
          <button
            onClick={() => {
              if (!agent.isGlobal) {
                setGlobalConfirmOpen(true);
              } else {
                onChange({ ...agent, isGlobal: false });
              }
            }}
            style={{ background: "none", border: "none", cursor: "pointer", padding: 0, lineHeight: 0, flexShrink: 0 }}
          >
            <SelectorIndicator selected={agent.isGlobal} size={16} />
          </button>
          <span style={{ fontFamily: "Montserrat, sans-serif", fontWeight: 500, fontSize: 10, color: "rgba(0,0,0,0.72)", letterSpacing: 0.15 }}>
            Tornar Agente Global
          </span>
          <InfoTooltipIcon
            tooltip="Torne este agente disponível para todos os usuários."
            iconColor="rgba(0,0,0,0.45)"
            position="top-center"
          />
        </div>
      </div>

      {globalConfirmOpen && (
        <div
          style={{
            position: "fixed",
            inset: 0,
            background: "rgba(0, 0, 0, 0.5)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            zIndex: 999999,
          }}
          onClick={() => setGlobalConfirmOpen(false)}
        >
          <div
            onClick={e => e.stopPropagation()}
            style={{
              background: "white",
              borderRadius: 10,
              padding: 24,
              maxWidth: 400,
              width: "90%",
              boxShadow: "0 18px 44px rgba(0,0,0,0.30)",
            }}
          >
            <h3 style={{ fontFamily: "Montserrat, sans-serif", fontSize: 16, fontWeight: 700, margin: "0 0 12 0" }}>
              Confirmar Tornar Global
            </h3>
            <p style={{ fontFamily: "Montserrat, sans-serif", fontSize: 12, color: "rgba(0,0,0,0.7)", margin: "0 0 24px 0" }}>
              Tem certeza que deseja tornar este agente global?
            </p>
            <div style={{ display: "flex", gap: 12, justifyContent: "flex-end" }}>
              <button
                onClick={() => setGlobalConfirmOpen(false)}
                style={{
                  height: 36,
                  padding: "0 16px",
                  borderRadius: 6,
                  border: "1px solid #d7d7d7",
                  background: "white",
                  cursor: "pointer",
                  fontFamily: "Montserrat, sans-serif",
                  fontSize: 12,
                }}
              >
                Cancelar
              </button>
              <button
                onClick={handleMakeGlobal}
                style={{
                  height: 36,
                  padding: "0 16px",
                  borderRadius: 6,
                  border: "none",
                  background: "black",
                  color: "white",
                  cursor: "pointer",
                  fontFamily: "Montserrat, sans-serif",
                  fontSize: 12,
                  fontWeight: 600,
                }}
              >
                Confirmar
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// ─── Tab: Inteligência ────────────────────────────────────────────────────────
// Não há modelos padrão do sistema: o agente só pode usar modelos customizados
// adicionados via "+ Modelo Customizado", cada um com seu próprio provedor,
// id real do modelo e chave de API (ver api/llm.ts callGemini/callOpenAI).
function TabInteligencia({ agent, onChange }: { agent: Agent; onChange: (a: Agent) => void }) {
  const intel = agent.inteligencia;
  const [modalOpen, setModalOpen] = useState(false);
  const [deleteModelId, setDeleteModelId] = useState<string | null>(null);
  const modelosCustomizados = intel.modelosCustomizados || [];
  const modelOptions = modelosCustomizados.map(model => ({ nome: model.nome, desc: model.modelId }));

  const handleDeleteCustomModel = (e: React.MouseEvent, modelId: string) => {
    e.stopPropagation();
    setDeleteModelId(modelId);
  };

  return (
    <>
      <div className="editor-panel-content" style={{ flex: 1, overflowY: "auto", padding: "12px 0 0", display: "flex", flexDirection: "column", gap: 14 }}>
        <div>
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 8, gap: 12, flexWrap: "wrap" }}>
            <span style={{ fontFamily: "Montserrat, sans-serif", fontSize: 10, color: "rgba(0,0,0,0.68)" }}>MODELOS DE IA</span>
            <button
              type="button"
              onClick={() => setModalOpen(true)}
              style={{
                height: 32,
                borderRadius: 0,
                border: "none",
                background: "transparent",
                color: "black",
                fontFamily: "Montserrat, sans-serif",
                fontSize: 11,
                fontWeight: 500,
                cursor: "pointer",
                padding: 0,
              }}
            >
              + Modelo Customizado
            </button>
          </div>
          <div style={{ background: "white", border: "1px solid #d7d7d7", borderRadius: 6, padding: 8, display: "flex", flexDirection: "column", gap: 6, height: 240, overflowY: modelOptions.length > 3 ? "auto" : "visible" }}>
            {modelOptions.length === 0 && (
              <div style={{ flex: 1, display: "flex", alignItems: "center", justifyContent: "center", textAlign: "center", padding: 16 }}>
                <span style={{ fontFamily: "Montserrat, sans-serif", fontSize: 11, color: "rgba(0,0,0,0.5)" }}>
                  Nenhum modelo configurado. Clique em "+ Modelo Customizado" para adicionar o modelo real da IA.
                </span>
              </div>
            )}
            {modelOptions.map(m => {
              const customModel = modelosCustomizados.find(model => model.nome === m.nome);
              return (
                <button
                  key={m.nome}
                  onClick={() => onChange({ ...agent, inteligencia: { ...intel, modelo: m.nome } })}
                  style={{ width: "100%", display: "flex", alignItems: "center", justifyContent: "space-between", padding: "10px 12px", background: "white", border: "1px solid #d7d7d7", borderRadius: 4, cursor: "pointer", gap: 12 }}
                >
                  <div style={{ textAlign: "left", minWidth: 0, flex: 1 }}>
                    <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap", marginBottom: 2, minWidth: 0 }}>
                      <div style={{ fontFamily: "Montserrat, sans-serif", fontSize: 11, color: "black", overflow: "hidden", whiteSpace: "nowrap", textOverflow: "ellipsis" }}>{m.nome}</div>
                      {customModel && (
                        <span style={{ height: 18, borderRadius: 999, background: "rgba(96, 88, 255, 0.09)", color: "#4F43F4", padding: "0 8px", display: "inline-flex", alignItems: "center", justifyContent: "center", fontFamily: "Montserrat, sans-serif", fontSize: 8, fontWeight: 700 }}>
                          CUSTOM
                        </span>
                      )}
                    </div>
                    <div style={{ fontFamily: "Montserrat, sans-serif", fontSize: 9, color: "rgba(0,0,0,0.5)", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{m.desc}</div>
                  </div>
                  <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                    {customModel && (
                      <button
                        onClick={(e) => handleDeleteCustomModel(e, customModel.id)}
                        style={{ background: "none", border: "none", cursor: "pointer", padding: 0, lineHeight: 0, display: "flex", alignItems: "center", justifyContent: "center" }}
                        title="Deletar modelo customizado"
                      >
                        <svg width="18" height="18" viewBox="0 0 26 24" fill="none">
                          <path d={F.trash} stroke="rgba(0,0,0,0.5)" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
                        </svg>
                      </button>
                    )}
                    <SelectorIndicator selected={intel.modelo === m.nome} />
                  </div>
                </button>
              );
            })}
          </div>
        </div>

        <div style={{ background: "white", border: "1px solid #d7d7d7", borderRadius: 6, padding: 12, display: "flex", flexDirection: "column", gap: 16, position: "relative" }}>
          {[{ label: "TEMPERATURA", key: "temperatura" as const }, { label: "TOP P", key: "topP" as const }].map(s => (
            <div key={s.key} style={intel.reasoning ? { filter: "blur(5px)", pointerEvents: "none", userSelect: "none" } : {}}>
              <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 8 }}>
                <LabelWithInfo 
                  label={s.label} 
                  info 
                  tooltip={
                    s.key === "temperatura" ? (
                      <div style={{ 
                        display: "flex", 
                        flexDirection: "column", 
                        gap: 8
                      }}>
                        <div style={{ display: "flex", flexDirection: "column", gap: 2 }}>
                          <div style={{ fontWeight: 600 }}>0.0 - 0.3 (Analítico/Focado)</div>
                          <div style={{ opacity: 0.8 }}>Ideal para análises, cálculos ou respostas que demandam precisão e consistência. O agente se manterá mais conservador e menos criativo.</div>
                        </div>
                        <div style={{ display: "flex", flexDirection: "column", gap: 2 }}>
                          <div style={{ fontWeight: 600 }}>0.7 - 1.0 (Equilibrado/Conversacional)</div>
                          <div style={{ opacity: 0.8 }}>Perfeito para chatbots, atendimento ao cliente ou interações naturais. Combina precisão com uma dose saudável de naturalidade.</div>
                        </div>
                        <div style={{ display: "flex", flexDirection: "column", gap: 2 }}>
                          <div style={{ fontWeight: 600 }}>1.2 - 2.0 (Criativo/Brainstorm)</div>
                          <div style={{ opacity: 0.8 }}>Ótimo para ideias, roteiros, histórias ou exploração de conceitos. O agente terá liberdade para gerar respostas mais variadas e inesperadas.</div>
                        </div>
                      </div>
                    ) : s.key === "topP" ? (
                      <div style={{ 
                        display: "flex", 
                        flexDirection: "column", 
                        gap: 8
                      }}>
                        <div style={{ display: "flex", flexDirection: "column", gap: 2 }}>
                          <div style={{ fontWeight: 600 }}>0.1 - 0.3 (Conservador/Seguro)</div>
                          <div style={{ opacity: 0.8 }}>Limita as respostas apenas às palavras mais prováveis, garantindo resultados seguros e previsíveis. Ideal para respostas que não podem se desviar do esperado.</div>
                        </div>
                        <div style={{ display: "flex", flexDirection: "column", gap: 2 }}>
                          <div style={{ fontWeight: 600 }}>0.5 - 0.8 (Equilibrado/Natural)</div>
                          <div style={{ opacity: 0.8 }}>Oferece um equilíbrio entre segurança e variedade, selecionando entre um grupo moderado de opções. Produz respostas naturais sem ser excessivamente criativo.</div>
                        </div>
                        <div style={{ display: "flex", flexDirection: "column", gap: 2 }}>
                          <div style={{ fontWeight: 600 }}>1.0 (Aberto/Considera tudo)</div>
                          <div style={{ opacity: 0.8 }}>Permite que o agente considere todas as palavras possíveis, abrindo espaço para mais variedade e surpresa. Ótimo para exploração criativa.</div>
                        </div>
                      </div>
                    ) : undefined
                  }
                />
                <div style={{ border: "1px solid #d7d7d7", borderRadius: 4, minWidth: 42, height: 18, display: "flex", alignItems: "center", justifyContent: "center", padding: "0 4px" }}>
                  <span style={{ fontFamily: "Montserrat, sans-serif", fontSize: 9 }}>{intel[s.key].toFixed(2)}</span>
                </div>
              </div>
              <input type="range" min={0} max={100} step={0.01} value={intel[s.key]}
                onChange={e => onChange({ ...agent, inteligencia: { ...intel, [s.key]: parseFloat(e.target.value) } })}
                disabled={intel.reasoning}
                style={{ width: "100%", accentColor: "black" }} />
            </div>
          ))}
          {intel.reasoning && (
            <div style={{ 
              position: "absolute", 
              top: "50%", 
              left: "50%", 
              transform: "translate(-50%, -50%)", 
              display: "flex", 
              alignItems: "center", 
              gap: 6,
              background: "rgba(255, 255, 255, 0.9)",
              padding: "8px 12px",
              borderRadius: 6,
              border: "1px solid #d7d7d7"
            }}>
              <Info size={12} color="rgba(0,0,0,0.5)" />
              <span style={{ fontFamily: "Montserrat, sans-serif", fontSize: 9, color: "rgba(0,0,0,0.5)" }}>
                Para ajustar manualmente, desative o Modo Raciocínio
              </span>
            </div>
          )}
        </div>

        <div style={{ display: "flex", gap: 12, flexWrap: "wrap" }}>
          <div style={{ flex: "1 1 220px", display: "flex", alignItems: "center", gap: 10, background: "white", border: "1px solid #d7d7d7", borderRadius: 6, padding: "10px 12px" }}>
            <button onClick={() => onChange({ ...agent, inteligencia: { ...intel, reasoning: !intel.reasoning } })}
              style={{ background: "none", border: "none", cursor: "pointer", padding: 0, lineHeight: 0, flexShrink: 0 }}
            >
              <SelectorIndicator selected={intel.reasoning} />
            </button>
            <span style={{ fontFamily: "Montserrat, sans-serif", fontSize: 10, color: "rgba(0,0,0,0.72)" }}>Modo Raciocínio (Reasoning)</span>
            <InfoTooltipIcon
              tooltip="Para modelos o1/o3. Bloqueia temperatura e força completion tokens."
              iconColor="rgba(0,0,0,0.45)"
            />
          </div>
          <div style={{ flex: "1 1 220px", display: "flex", alignItems: "center", gap: 10, background: "white", border: "1px solid #d7d7d7", borderRadius: 6, padding: "10px 12px" }}>
            <span style={{ fontFamily: "Montserrat, sans-serif", fontSize: 10, color: "rgba(0,0,0,0.72)", flex: 1 }}>Max Output Tokens</span>
            <input 
              type="number" 
              value={intel.maxTokens} 
              onChange={e => {
                const value = parseInt(e.target.value);
                if (isNaN(value) || value < 1) {
                  onChange({ ...agent, inteligencia: { ...intel, maxTokens: 1 } });
                } else if (value > 4096) {
                  onChange({ ...agent, inteligencia: { ...intel, maxTokens: 4096 } });
                } else {
                  onChange({ ...agent, inteligencia: { ...intel, maxTokens: value } });
                }
              }}
              min={1}
              max={4096}
              className="no-spinner"
              style={{ 
                width: 70, 
                height: 24, 
                border: "1px solid #d7d7d7", 
                borderRadius: 4, 
                padding: "0 6px", 
                fontFamily: "Montserrat, sans-serif", 
                fontSize: 10, 
                textAlign: "right", 
                outline: "none", 
                background: "white"
              }} 
            />
          </div>
        </div>
      </div>

      <NovoModeloModal
        open={modalOpen}
        onClose={() => setModalOpen(false)}
        onSave={model => {
          const nextCustomModels = [
            ...modelosCustomizados.filter(item =>
              item.nome.toLowerCase() !== model.nome.toLowerCase()
              && item.modelId.toLowerCase() !== model.modelId.toLowerCase()
            ),
            model,
          ];

          onChange({
            ...agent,
            inteligencia: {
              ...intel,
              modelo: model.nome,
              modelosCustomizados: nextCustomModels,
            },
          });
        }}
      />

      <AlertDialog open={deleteModelId !== null} onOpenChange={(open) => !open && setDeleteModelId(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Deletar este modelo customizado?</AlertDialogTitle>
            <AlertDialogDescription>
              Esta ação não pode ser desfeita. Tem certeza que deseja deletar este modelo customizado?
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancelar</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => {
                if (deleteModelId) {
                  const deletedModel = modelosCustomizados.find(m => m.id === deleteModelId);
                  onChange({
                    ...agent,
                    inteligencia: {
                      ...intel,
                      modelosCustomizados: modelosCustomizados.filter(m => m.id !== deleteModelId),
                      // Sem modelos fixos para cair de volta — se o modelo deletado era o
                      // selecionado, limpa a seleção em vez de apontar pra algo inexistente.
                      modelo: deletedModel && intel.modelo === deletedModel.nome ? "" : intel.modelo,
                    },
                  });
                  setDeleteModelId(null);
                }
              }}
            >
              Deletar
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

// ─── Tab: Persona ─────────────────────────────────────────────────────────────
